{
  "claims": [
    {
      "claim": "Tenofovir, a close acyclic nucleotide phosphonate analog of the query, has low oral bioavailability as the parent drug; only lipophilic prodrugs such as tenofovir disoproxil fumarate achieve approximately 25% oral bioavailability, indicating that the unmodified phosphonate parent is below the 20% threshold.",
      "evidence_role": "supportive",
      "molecule_ids": ["Molecule 13"],
      "record_ids": ["Record 13-1", "Record 13-2", "Record 13-3", "Record 13-4", "Record 13-5", "Record 13-6", "Record 13-7", "Record 13-8", "Record 13-9", "Record 13-10"]
    },
    {
      "claim": "Adefovir dipivoxil, the bis-ester prodrug of the query molecule adefovir, reaches only about 30% oral bioavailability in humans after fasting; because this prodrug was designed to improve the poor absorption of the parent phosphonate, the unmodified adefovir is expected to have lower oral bioavailability, below 20%.",
      "evidence_role": "supportive",
      "molecule_ids": ["Molecule 11"],
      "record_ids": ["Record 11-1", "Record 11-2", "Record 11-3"]
    },
    {
      "claim": "A closely related adenine phosphonate, 9-[2-(phosphonomethoxy)-ethoxy]adenine, showed low oral bioavailability (0–26%, mostly below 20%) in mice even when administered as various diester prodrugs, supporting the expectation that unmodified adenine phosphonates such as adefovir have poor oral bioavailability.",
      "evidence_role": "supportive",
      "molecule_ids": ["Molecule 12"],
      "record_ids": ["Record 12-1", "Record 12-2", "Record 12-3", "Record 12-4", "Record 12-5", "Record 12-6", "Record 12-7", "Record 12-8", "Record 12-9", "Record 12-10", "Record 12-11", "Record 12-12", "Record 12-13", "Record 12-14", "Record 12-15", "Record 12-16"]
    },
    {
      "claim": "Tenofovir, a phosphonate nucleotide analog, has very low Caco-2 permeability (Papp ~0.1 × 10^-6 cm/s) and permeates mainly by passive paracellular diffusion, consistent with poor oral absorption of ionized phosphonate nucleotides; this barrier transfers to the similarly charged adefovir molecule.",
      "evidence_role": "supportive",
      "molecule_ids": ["Molecule 16", "Molecule 18"],
      "record_ids": ["Record 16-3", "Record 18-1", "Record 18-2", "Record 18-4"]
    },
    {
      "claim": "Nucleoside analogs without the phosphonate group, such as acyclovir (F=20%), didanosine (F=22–28% fasting), cladribine (F=40–46% fasting), and fludarabine monophosphate (F=70%), show higher oral bioavailability, but they lack the ionized phosphonic acid moiety that dominates the absorption barrier for the query; therefore they are less transferable and do not overturn the phosphonate-based low-bioavailability evidence.",
      "evidence_role": "contradictory",
      "molecule_ids": ["Molecule 1", "Molecule 3", "Molecule 10", "Molecule 5"],
      "record_ids": ["Record 1-1", "Record 3-1", "Record 3-2", "Record 10-1", "Record 10-2", "Record 5-1"]
    }
  ],
  "final_prediction": "fail"
}
